const sections=[['experience','01','EXPERIENCE','Places I’ve contributed.'],['projects','02','PROJECTS','Things I’ve built.'],['about','03','ABOUT ME','The person behind the folders.'],['education','04','EDUCATION','A foundation. An open question.'],['contact','05','CONTACT','Let’s make a connection.']];
const entries={projects:[
{title:'Milemark',id:'P—001',category:'RUNNING × SOFTWARE',subtitle:'A little more intention behind every mile.',body:'A marathon training dashboard built around my own running. It brings run history, recovery signals, race goals, and a progressive training calendar into one place.',notes:'Built a Python Garmin bridge, validated imports, and interactive React charts. Daily mileage combines multiple runs; swimming and cycling stay out of running calculations. Garmin connections currently run locally; the browser demo uses illustrative data.',tags:['Python','React','TypeScript','Garmin'],art:'route',link:'https://github.com/nikhiltrip/milemark',status:'WORKING LOCAL APP'},
{title:'UCLA ATS',id:'P—002',category:'FULL-STACK SYSTEMS',subtitle:'A clearer path from application to decision.',body:'A collaborative application-tracking project covering form creation, applications, reviewer workflows, candidate stages, analytics, and CSV exports.',notes:'A React interface backed by Node.js and PostgreSQL, with database migrations and Docker configuration. The repository contains the application; a public sandbox is not currently available.',tags:['React','Node.js','PostgreSQL','Docker'],art:'cards',link:'https://github.com/beck-2/ATS',status:'SOURCE AVAILABLE'},
{title:'Lorenz Equations',id:'P—003',category:'MATHEMATICS × COMPUTATION',subtitle:'Small differences. Very different futures.',body:'An exploration of the Lorenz system and the way nearby initial conditions evolve into dramatically different trajectories.',notes:'Numerically integrates trajectories, compares perturbed initial conditions, and plots time-series and three-dimensional attractors. A high-school project that still captures something I enjoy: using code to make an abstract idea tangible.',tags:['Python','Numerical methods','Visualization'],art:'lorenz',link:'https://github.com/nikhiltrip/LorenzEquations',status:'COMPUTATIONAL EXPLORATION'},
{title:'CampusTrendsML',id:'P—004',category:'TEXT × DATA',subtitle:'Looking for patterns in campus conversation.',body:'A project exploring how text, timing, and engagement signals can help describe discussion patterns in a university community.',notes:'The current repository includes ingestion, cleaning, text preprocessing, and temporal and sentiment features. Modeling and evaluation are still in progress.',tags:['Python','Pandas','Text processing'],art:'signals',link:'https://github.com/nikhiltrip/campustrends',status:'IN DEVELOPMENT'},
{title:'PropShop',id:'P—005',category:'DATA PIPELINES × DASHBOARDS',subtitle:'Turning scattered odds into something readable.',body:'A prototype for collecting and comparing sports-projection and odds data, with an interface for searching and inspecting estimated pricing differences.',notes:'Includes Python collection logic, probability calculations, an Express API, and a React dashboard. Live collection and refresh reliability need further work; this is not a public production service.',tags:['Python','Express','React','Data collection'],art:'bars',link:'https://github.com/nikhiltrip/propshop',status:'PROTOTYPE'}],experience:[
{title:'Visa',id:'E—001',category:'SOFTWARE ENGINEERING INTERN',subtitle:'Engineering for financial investigation.',body:'Worked with Visa’s Global Tokenization Services team on an internal conversational assistant for investigating financial data.',notes:'Used Spring Boot, Spring AI, Redis, PostgreSQL, and vector retrieval to connect natural-language questions with source information and exact database aggregation. Developed evaluation cases and QA workflows. Internal implementation and data remain private.',tags:['Java','Spring Boot','PostgreSQL','Redis'],art:'signals',status:'SUMMER 2026'},
{title:'UCLA Stress Lab',id:'E—002',category:'UNDERGRADUATE RESEARCH',subtitle:'Making complex audio ready for careful analysis.',body:'Ongoing work at UCLA’s Semel Institute, building tools for clinical-audio processing and exploratory stress research.',notes:'Developed local transcription, acoustic-feature extraction, coverage checks, and transcript-quality workflows using Whisper, Librosa, and Pandas. The work supports exploratory analysis; it is not a clinically validated stress diagnostic. Participant data is not shared here.',tags:['Python','Whisper','Librosa','Research'],art:'wave',status:'MARCH 2026 — PRESENT'},
{title:'Rivet Industries',id:'E—003',category:'SOFTWARE ENGINEERING INTERN',subtitle:'From sensor images to dependable workflows.',body:'Worked on Python data-processing workflows for SPAD sensor images and engineering infrastructure.',notes:'Experience included ETL, signal-processing workflows, automated testing, and container-based development and deployment tooling. Company code and data are not publicly available.',tags:['Python','ETL','Docker','CI/CD'],art:'bars',status:'SUMMER 2025'}]};
let current='projects',selected=0,artifactFrame;const app=document.querySelector('#app'),archive=document.querySelector('#archive');
document.querySelector('#drawers').innerHTML=sections.map(([key,no,label])=>`<button class="drawer" data-section="${key}" aria-label="Open ${label.toLowerCase()} drawer"><span class="drawer-no">${no}</span><span class="drawer-label">${label}</span><span class="handle"></span><span class="drawer-arrow">↗</span></button>`).join('');
function openSection(key,focus=true){current=key;selected=0;const s=sections.find(x=>x[0]===key);if(!s)return;app.classList.add('entered');archive.hidden=false;document.querySelector('#section-number').textContent=s[1];document.querySelector('#section-kicker').textContent=`DRAWER ${s[1]} / ${s[2]}`;document.querySelector('#section-title').textContent=key==='experience'?'Experience.':key==='projects'?'Selected work.':key==='about'?'Outside the index.':key==='education'?'Still learning.':'Say hello.';document.querySelectorAll('.drawer').forEach(b=>{b.classList.toggle('active',b.dataset.section===key);b.setAttribute('aria-expanded',String(b.dataset.section===key))});render();history.replaceState(null,'',`#${key}`);if(focus){archive.tabIndex=-1;archive.focus({preventScroll:true});window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}}
function render(){cancelAnimationFrame(artifactFrame);const content=document.querySelector('#section-content');if(entries[current]){content.innerHTML=`<div class="folder-grid"><div class="folder-list" role="group" aria-label="${current} files">${entries[current].map((e,i)=>`<button class="folder-tab ${i===selected?'selected':''}" data-entry="${i}" aria-pressed="${i===selected}"><small>${e.id}</small><b>${e.title}</b><span>↗</span></button>`).join('')}</div><article class="document" id="document"></article></div>`;renderDocument();return}if(current==='about'){content.innerHTML=`<div class="about-layout"><div><h3 class="about-title">Curiosity doesn’t<br>keep office hours.</h3><p class="about-copy">I’m Nikhil, a computer science student at UCLA. I enjoy finding the point where an interesting idea becomes something someone can actually use.</p><p class="about-copy">My work has taken me through financial software, sensor-data pipelines, clinical-audio research, and projects inspired by my own everyday life.</p><p class="about-copy">I’m interested in software systems, applied machine learning, and the questions that sit between disciplines.</p><div class="profile-meta"><span>BASED IN<br>LOS ANGELES</span><span>CURRENTLY<br>BUILDING & LEARNING</span></div></div><aside class="hobby-note"><h3>Beyond the work.</h3><div class="hobby"><small>01</small>Running the long way home</div><p>I’ve run several half marathons and am currently training for a marathon. That’s where the idea for Milemark began.</p><div class="hobby"><small>02</small>Writing about philosophy</div><div class="hobby"><small>03</small>Cooking something new</div><div class="hobby"><small>04</small>Weightlifting</div><p>A few things that keep me curious, grounded, and away from a screen.</p></aside></div>`}else if(current==='education'){content.innerHTML=`<div class="education-card"><span class="eyebrow">LOS ANGELES, CALIFORNIA</span><h3>University of California,<br>Los Angeles</h3><p>Bachelor of Science in Computer Science<br>Expected graduation: June 2028</p><div class="tags"><span>UCLA</span><span>Computer Science</span><span>Class of 2028</span></div></div><article class="document"><h4>QUESTIONS I KEEP COMING BACK TO</h4><div class="interest-list"><p><small>01</small>How do we build dependable systems?</p><p><small>02</small>What can we learn from messy data?</p><p><small>03</small>How can software support research?</p><p><small>04</small>What makes a tool worth using?</p></div></article>`}else{content.innerHTML=`<h3 class="contact-title">Good things start<br>with a conversation.</h3><p class="contact-sub">Want to talk about software, research, or something you found in the archive? I’d love to hear from you.</p><a class="contact-link" href="mailto:nikhiltrip1@gmail.com"><span>Email <small>nikhiltrip1@gmail.com</small></span><span>↗</span></a><a class="contact-link" href="https://github.com/nikhiltrip" target="_blank" rel="noopener"><span>GitHub <small>@nikhiltrip</small></span><span>↗</span></a><a class="contact-link" href="Nikhil-Tripathi-Resume.pdf" target="_blank" rel="noopener"><span>Résumé <small>PDF / OPEN FILE</small></span><span>↗</span></a><p class="contact-note">FROM THE PERSONAL ARCHIVE OF NIKHIL TRIPATHI.</p>`}}
function renderDocument(){const e=entries[current][selected];document.querySelectorAll('.folder-tab').forEach((b,i)=>{b.classList.toggle('selected',i===selected);b.setAttribute('aria-pressed',String(i===selected))});document.querySelector('#document').innerHTML=`<div class="document-head"><span>${e.category}</span><span>${e.id}</span></div><h3>${e.title}</h3><p class="lead">${e.subtitle}</p><div class="artifact"><canvas id="artifact"></canvas><span class="artifact-label">${e.art==='lorenz'?'LORENZ / LIVE NUMERICAL SKETCH':'VISUAL STUDY / '+e.category}</span><span class="artifact-number">${e.id}</span></div><p>${e.body}</p><h4>INSIDE THE FILE</h4><p>${e.notes}</p><div class="tags">${e.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="doc-links">${e.link?`<a href="${e.link}" target="_blank" rel="noopener">Explore source ↗</a>`:''}<span class="contact-note" style="margin:0">${e.status}</span></div>`;drawArtifact(e.art)}
function closeArchive(){cancelAnimationFrame(artifactFrame);archive.hidden=true;app.classList.remove('entered');history.replaceState(null,'',location.pathname);document.querySelectorAll('.drawer').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-expanded','false')});document.querySelector('#enter').focus({preventScroll:true})}
document.addEventListener('click',e=>{const s=e.target.closest('[data-section]');if(s)openSection(s.dataset.section);const entry=e.target.closest('[data-entry]');if(entry){selected=Number(entry.dataset.entry);cancelAnimationFrame(artifactFrame);renderDocument()}});document.querySelector('#enter').onclick=()=>openSection('projects');document.querySelector('#close').onclick=closeArchive;document.querySelector('.wordmark').onclick=e=>{e.preventDefault();closeArchive()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeArchive()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function drawArtifact(type){const c=document.querySelector('#artifact'),ctx=c.getContext('2d');const w=c.width=c.clientWidth*2,h=c.height=c.clientHeight*2;let t=0;let points=[],x=.1,y=0,z=0;for(let i=0;i<3200;i++){const dt=.006;const dx=10*(y-x),dy=x*(28-z)-y,dz=x*y-8/3*z;x+=dx*dt;y+=dy*dt;z+=dz*dt;if(i>200)points.push([x,y,z])}function frame(){ctx.clearRect(0,0,w,h);ctx.strokeStyle='#85966f18';ctx.lineWidth=1;for(let i=0;i<w;i+=36){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,h);ctx.stroke()}for(let i=0;i<h;i+=36){ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(w,i);ctx.stroke()}ctx.lineWidth=1.8;ctx.strokeStyle='#e6b17f';ctx.beginPath();if(type==='lorenz'){for(let i=0;i<points.length;i++){const p=points[i],xx=w/2+(p[0]*Math.cos(t*.003)+p[1]*Math.sin(t*.003))*h/58,yy=h*.86-p[2]*h/60;i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)}}else if(type==='route'){for(let i=0;i<200;i++){const a=i/199,xx=w*.15+a*w*.7+Math.sin(a*16)*18,yy=h*.5+Math.sin(a*8)*h*.22+Math.cos(a*19)*10;i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)}ctx.stroke();const a=(t%600)/600;ctx.fillStyle='#f3e4b5';ctx.beginPath();ctx.arc(w*.15+a*w*.7+Math.sin(a*16)*18,h*.5+Math.sin(a*8)*h*.22+Math.cos(a*19)*10,5,0,Math.PI*2);ctx.fill()}else if(type==='bars'||type==='cards'){for(let i=0;i<18;i++){const hh=20+Math.abs(Math.sin(i*1.7+t*.006))*h*.43;ctx.fillStyle=i%3===0?'#d0a979':'#728869';ctx.fillRect(w*.13+i*w*.042,h*.73-hh,w*.024,hh)}}else{for(let i=0;i<w;i++){const xx=i/w;const yy=h*.49+Math.sin(xx*23+t*.018)*Math.sin(xx*Math.PI)*h*.16+Math.sin(xx*71-t*.01)*h*.055;i?ctx.lineTo(i,yy):ctx.moveTo(i,yy)}}ctx.stroke();t++;if(!reduced)artifactFrame=requestAnimationFrame(frame)}frame()}
const dust=document.querySelector('#dust'),d=dust.getContext('2d');let dw,dh,t=0;function size(){dw=dust.width=dust.clientWidth;dh=dust.height=dust.clientHeight}size();window.addEventListener('resize',size);const motes=Array.from({length:45},()=>[Math.random(),Math.random(),Math.random()]);function particles(){d.clearRect(0,0,dw,dh);for(const [x,y,r]of motes){d.fillStyle=`rgba(219,223,183,${.04+r*.15})`;d.beginPath();d.arc((x*dw+Math.sin(t*.002+r*8)*12)%dw,(y*dh-t*(.03+r*.04)+dh*10)%dh,.4+r*.7,0,7);d.fill()}t++;if(!reduced)requestAnimationFrame(particles)}particles();const initial=location.hash.slice(1);if(sections.some(s=>s[0]===initial))openSection(initial,false);
